import{_ as s,a0 as o,w as r,s as u,ao as a,I as p,x as l,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何從 Linux 的文件管理器中加密文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何從 Linux 的文件管理器中加密文件 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從 Linux 的文件管理器中加密文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從 Linux 的文件管理器中加密文件 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180316 How to Encrypt Files From Within a File Manager","title":"如何從 Linux 的文件管理器中加密文件","tag":"201809","desc":""},"relativePath":"201809/20180316 How to Encrypt Files From Within a File Manager.md","filePath":"[post].md"}'),d={name:"201809/20180316 How to Encrypt Files From Within a File Manager.md"};function g(h,i,m,f,x,k){const t=o("Link");return r(),u("div",null,[i[19]||(i[19]=a('<h1 id="如何從-linux-的文件管理器中加密文件" tabindex="-1">如何從 Linux 的文件管理器中加密文件 <a class="header-anchor" href="#如何從-linux-的文件管理器中加密文件" aria-label="Permalink to “如何從 Linux 的文件管理器中加密文件”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/encryption.jpg?itok=Pk3_x5hz" alt=""></p><p>Linux 桌面版和服務器版具有卓越的安全性。然而這並不意味着你可以放鬆警惕。你應該一直認為你的數據總是很快就會被破壞。也就是説，你可能需要使用各種加密工具。比如 GnuPG，它可以讓你加密和解密文件等更多功能。GnuPG 的一個問題是一些用户不想在命令列輸入那麼複雜的命令。如果是這樣的話，你可以轉向桌面文件管理器。許多 Linux 桌面版包含了簡易的加密和解密文件的功能，如果這種功能沒有內置，那麼也是很容易添加的。</p><p>我將引導你完成從三個流行的 Linux 文件管理器中對文件進行加密和解密過程：</p><ul><li>Nautilus （即 GNOME Files）</li><li>Dolphin</li><li>Thunar</li></ul><h3 id="安裝-gnupg" tabindex="-1">安裝 GnuPG <a class="header-anchor" href="#安裝-gnupg" aria-label="Permalink to “安裝 GnuPG”">​</a></h3>',6)),p("p",null,[i[1]||(i[1]=l("在我們討論如何處理這個問題之前，我們必須確保你的系統包含了必要的基本組件 —— ",-1)),e(t,{href:"https://www.gnupg.org/"},{default:n(()=>[...i[0]||(i[0]=[l("GnuPG",-1)])]),_:1}),i[2]||(i[2]=l("。大多數發行版本都包含 GnuPG。 在某些偶然情況下，你使用的是沒有自帶 GnuPG 的發行版，以下是安裝方法：",-1))]),i[20]||(i[20]=a('<ul><li>基於 Ubuntu 的發行版： <code>sudo apt install gnupg</code></li><li>基於 Fedora 的發行版： <code>sudo yum install gnupg</code></li><li>openSUSE： <code>sudo zypper in gnupg</code></li><li>基於 Arch 的發行版：<code>sudo pacman -S gnupg</code></li></ul><p>無論你是剛剛安裝了 GnuPG，還是默認安裝的，你都必須創建一個 GPG 密鑰才能使用。每個桌面版都使用不同的 GUI 工具完成這個工作（或者甚至根本沒有包含一個完成這個任務的 GUI 工具），所以讓我們從命令列中創建這個密鑰。打開終端窗口並輸入以下指令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg --gen-key</span></span></code></pre></div><p>然後，你將被要求回答以下問題。除非你有充分的理由，否則你可以接受默認值：</p><ul><li>你想要哪種密鑰？</li><li>你想要多長的密鑰？</li><li>密鑰有效期？</li></ul><p>一旦你回答了這些問題，輸入 <code>y</code> 來表示答案是正確的。接下來你需要提供以下信息：</p><ul><li>真實姓名。</li><li>Email 地址。</li><li>備註。</li></ul><p>完成上述操作後，然後在提示的時候輸入 <code>O</code> （即 ok）。然後，你將被要求為新密鑰輸入一個密碼。一旦系統收集到了足夠的熵（你需要在桌面上做一些工作才能做到這一點，LCTT 譯註：比如隨便敲擊鍵盤），你的密鑰就會被創建，然後你就可以開始工作了。</p><p>讓我們看看如何從文件管理器中加密/解密文件：</p><h3 id="nautilus" tabindex="-1">Nautilus <a class="header-anchor" href="#nautilus" aria-label="Permalink to “Nautilus”">​</a></h3><p>讓我們從默認的 GNOME 文件管理器開始，因為它是最簡單的。Nautilus 不需要額外安裝什麼或額外的工作就可以從精心設計的界面內加密/解密文件。一旦你創建完 gpg 密鑰後，就可以打開文件管理器，導航到包含要加密的文件的目錄，右鍵單擊要加密的文件，然後從菜單中選擇 “Encrypt” （圖1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/nautilus.jpg?itok=ae7Gtj60" alt="nautilus" title="nautilus"></p><p><em>圖1：從 Nautilus 中加密文件。</em></p><p>你將被要求選擇一個收件人（或者收件人列表 —— 圖2）。注意：收件人將是那些你已經導入了公鑰的用户。選擇所需的密鑰，然後從簽名信息下拉列表中選擇你的密鑰（電子郵件地址）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/nautilus_2.jpg?itok=3ht7j63n" alt="nautilus" title="nautilus"></p><p><em>圖2：選擇收件人和簽名者。</em></p><p>注意：你還可以選擇僅使用密碼來加密文件。如果文件將保留在你的本地機器上，這一點非常重要（稍後將詳細介紹）。一旦你設置好加密後，單擊 “OK” 並（在提示時）輸入 gpg 密鑰的密碼。文件將被加密（現在文件名以 .gpg 結尾）並保存在工作目錄中。現在你可以將加密後的文件發送給在加密過程中已選擇的收件人。</p><p>比如説（有你的公鑰的）某人已經給你發送了一個加密文件。保存該文件，打開文件管理器，導航到該文件所在的目錄，右擊這個加密文件，選擇 “Open With Decrypt File”，給文件一個新名稱（不帶 .gpg 的擴展名），然後單擊“Save”。當提示時，輸入你的 gpg 密鑰的密碼，該文件就會被解密並準備使用。</p><h3 id="dolphin" tabindex="-1">Dolphin <a class="header-anchor" href="#dolphin" aria-label="Permalink to “Dolphin”">​</a></h3><p>在 KDE 前端，必須安裝一個軟件包才能使用 Dolphin 文件管理器進行加密/解密。 登錄到你的 KDE 桌面，打開終端窗口，然後輸入以下命令（我正在使用 Neon 進行演示。如果你的發行版不是基於 Ubuntu 的，則必須相應地更改命令）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install kgpg</span></span></code></pre></div><p>安裝完畢後，註銷並重新登錄 KDE 桌面。 你可以打開 Dolphin 並右鍵單擊要加密的文件。 由於這是你第一次使用 kgpg，因此你必須完成快速設置嚮導（不言自明）。當完成該向導後，你可以返回該文件，右鍵單擊它（圖3），然後選擇 Encrypt File。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/kde_0.jpg?itok=KSTctVw0" alt="Dolphin" title="Dolphin"></p><p><em>圖3：在 Dolphin 中加密文件。</em></p><p>系統將提示你選擇用於加密的密鑰（圖4）。 進行選擇並單擊 “OK”。 該文件將被加密，而且你已準備好將其發送給收件人。</p><p>注意：使用 KDE 的 Dolphin 文件管理器市，你無法僅使用密碼加密。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/kde_2.jpg?itok=CeqWikNl" alt="Dolphin" title="Dolphin"></p><p><em>圖4：選擇要加密的收件人。</em></p><p>如果你收到來自有你的公鑰的用户的加密文件（或者你有一個自己加密的文件），請打開 Dolphin，導航到相關文件，雙擊該文件，為該文件指定一個新名稱 ，鍵入加密密碼並單擊 “OK”。 你現在可以讀取到新解密的文件。 如果你使用自己的密鑰加密了該文件，則不會提示你鍵入密碼（因為它已經被存儲了）。</p><h3 id="thunar" tabindex="-1">Thunar <a class="header-anchor" href="#thunar" aria-label="Permalink to “Thunar”">​</a></h3><p>Thunar 文件管理器有點棘手。 沒有任何額外的軟件包可供安裝；相反，你需要為了加密創建新的自定義操作。完成此操作後，你將能夠在文件管理器中執行此操作。</p><p>要創建自定義操作，請打開 Thunar 文件管理器，然後單擊 “Edit &gt; Configure Custom Actions”。 在所得到的窗口中，單擊 “+” 按鈕（圖5）併為加密操作輸入以下內容：</p><ul><li>名稱：加密</li><li>描述：文件加密</li><li>命令：<code>gnome-terminal -x gpg --encrypt --recipient ％f</code></li></ul><p>單擊 “OK” 以保存此操作。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/thunar.jpg?itok=fXcHk08B" alt="Thunar" title="Thunar"></p><p><em>圖5：在Thunar中創建自定義操作。</em></p><p>注意：如果 gnome-terminal 不是你的默認終端，請替換該命令以打開你的默認終端。</p><p>你還可以創建僅使用密碼（而非密鑰）加密的操作。 為此，該操作的詳細動作將會是以下內容：</p><ul><li>名稱：加密密碼</li><li>説明：僅使用密碼加密</li><li>命令：<code>gnome-terminal -x gpg -c ％f</code></li></ul><p>你不需要為解密過程創建一個自定義操作，因為 Thunar 已經知道如何處理一個加密文件。 要解密文件，只需（在 Thunar 中）右鍵單擊它，選擇 “Open With Decrypt File”，為解密文件命名，然後（在提示時）鍵入加密密碼。 Viola，你的加密文件已被解密並可以使用。</p><h3 id="一個警告" tabindex="-1">一個警告 <a class="header-anchor" href="#一個警告" aria-label="Permalink to “一個警告”">​</a></h3><p>請注意：如果你使用自己的密鑰加密自己的文件，則無需輸入加密密碼來解密它們（因為你的公鑰已存儲）。 但是，如果你收到（擁有你的公鑰的）其他人的文件，則需要輸入你的密碼。 如果你想要存儲自己的加密文件，而不是使用密鑰來加密它們，請使用僅使用密碼加密。 Nautilus 和Thunar（但不是 KDE）可以做到這一點。 通過選擇密碼加密（通過密鑰加密），當你解密文件時，它將始終提示你輸入密碼。</p><h3 id="其他文件管理器" tabindex="-1">其他文件管理器 <a class="header-anchor" href="#其他文件管理器" aria-label="Permalink to “其他文件管理器”">​</a></h3><p>還有很多其它的文件管理器，它們中的一些可以使用加密，有些則不能。 你很有可能正在使用這三種工具中的一種，因此不僅可以將加密 / 解密添加到上下文菜單，而且是非常容易。 嘗試一下，看看它是否會使加密和解密的過程變得更容易。</p>',44)),p("p",null,[i[4]||(i[4]=l("從 Linux 基金會和 edX 免費提供的",-1)),e(t,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:n(()=>[...i[3]||(i[3]=[l("“Linux 介紹”",-1)])]),_:1}),i[5]||(i[5]=l("課程瞭解更多關於 Linux 的信息。",-1))]),i[21]||(i[21]=p("hr",null,null,-1)),p("p",null,[i[7]||(i[7]=l("via: ",-1)),e(t,{href:"https://www.linux.com/learn/intro-to-linux/2018/3/how-encrypt-files-within-file-manager"},{default:n(()=>[...i[6]||(i[6]=[l("https://www.linux.com/learn/intro-to-linux/2018/3/how-encrypt-files-within-file-manager",-1)])]),_:1})]),p("p",null,[i[11]||(i[11]=l("作者：",-1)),e(t,{href:"https://www.linux.com/users/jlwallen"},{default:n(()=>[...i[8]||(i[8]=[l("JACK WALLEN",-1)])]),_:1}),i[12]||(i[12]=l(" 譯者：",-1)),e(t,{href:"https://github.com/Auk7f7"},{default:n(()=>[...i[9]||(i[9]=[l("Auk7f7",-1)])]),_:1}),i[13]||(i[13]=l(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:n(()=>[...i[10]||(i[10]=[l("wxy",-1)])]),_:1})]),p("p",null,[i[16]||(i[16]=l("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[14]||(i[14]=[l("LCTT",-1)])]),_:1}),i[17]||(i[17]=l(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:n(()=>[...i[15]||(i[15]=[l("Linux中國",-1)])]),_:1}),i[18]||(i[18]=l(" 榮譽推出",-1))])])}const c=s(d,[["render",g]]);export{b as __pageData,c as default};
